// ====== REGISTRY — content files register themselves through these functions (they define no other globals) ======
// Files are loaded in the order listed by abc/manifest.js (generated by `node tools/check.js --fix`).
// Every contract below is checked by tools/check.js.
var ABC = {
  config: null,      // abc/config.js (see there)
  langs: {},         // code → LANG fields + { strings, words[], info{} }   (abc/lang/<code>/*)
  concepts: [],      // language-neutral concepts (abc/concepts.js)
  conceptById: {},
  art: {},           // id → SVG body (abc/art.js)
  modules: [],       // subjects (abc/modules/<id>/module.js)
  views: {},         // screen types (abc/core/views/*.js)
  games: {},         // game types (abc/core/games/*.js)
  errors: []         // problems found while loading — tools/check.js fails on them
};
const abcLang = code => ABC.langs[code] || (ABC.langs[code] = { code, strings: {}, words: [], info: {} });
const abcMerge = (a, b) => { for (const k in b) a[k] = (b[k] && typeof b[k] === 'object' && !Array.isArray(b[k]) && typeof a[k] === 'object') ? abcMerge(a[k], b[k]) : b[k]; return a; };

function CONFIG(c) { ABC.config = c; }
// LANG (abc/lang/<code>/grammar.js)
//   required: name, flag, bcp47, letters ("A B … Ch …", space-separated units), forms(entry, word) → { sg:[a, the], pl:[…] } | null
//   optional: dir ('rtl'), keepCase (don't lower-case example words), spell(letter) → how a letter is said,
//             fold(text) → search folding (e.g. ß → ss), voices (RegExp of preferred device voice names),
//             checkForms(entry) / checkWord(entry) → warning text (tools/check.js)
//   module data (only if a module lists it in `needs`): numbers [10 words], sayLetter(name, word, inside), groups
function LANG(code, def) { Object.assign(abcLang(code), def); }
// UI strings of a language (abc/lang/<code>/strings.js); the base language (config.baseLanguage) fills any gap
function STRINGS(code, s) { abcMerge(abcLang(code).strings, s); }
// words (abc/lang/<code>/words.js):  const w = WORDS('ro');  w('cow', { w: 'va/că', … })  — '/' marks syllables
function WORDS(code) {
  const L = abcLang(code), seen = new Set(L.words.map(x => x.id));
  return (id, e) => {
    if (seen.has(id)) ABC.errors.push(`${code}/words: "${id}" defined twice`);
    seen.add(id); L.words.push(Object.assign({ id }, e));
  };
}
// "What is it?" cards (abc/lang/<code>/info.js):  const i = INFO('ro');  i('rainbow', { title, lines: [[emoji, sentence], …] })
function INFO(code) {
  const L = abcLang(code);
  return (id, card) => { if (L.info[id]) ABC.errors.push(`${code}/info: "${id}" defined twice`); L.info[id] = card; };
}
// a concept (abc/concepts.js): stable ASCII id, picture, optional { gloss } (a note for translators)
function C(id, pic, opts) {
  if (ABC.conceptById[id]) ABC.errors.push(`concepts: "${id}" defined twice`);
  const c = Object.assign({ id, pic, order: ABC.concepts.length }, opts);
  ABC.concepts.push(c); ABC.conceptById[id] = c;
}
// a picture that is content (abc/art.js)
function ART(id, svg) { if (ABC.art[id]) ABC.errors.push(`art: "${id}" defined twice`); ABC.art[id] = svg; }
// MODULE (abc/modules/<id>/module.js) — a subject:
//   { section, ages: [from, to], needs?: [LANG fields it reads], build(code) → its own content (S), tiles: [TILE],
//     check?(code, S, strings, report) → extra content checks }
// TILE: { id, icon (emoji or short text), view?, items?: S → ITEM[], game?: { type, items?, prompts?, lower?, ask?(item, round) → key },
//         index?: grid of all items, search?: found by the universal search, section?, ages? }
// Module strings (abc/modules/<id>/lang/<code>.js): { tiles: { <tileId>: [learn label, game label] }, games: { <key>: spoken question } }
function MODULE(id, def) { ABC.modules.push(Object.assign({ id, strings: {} }, def)); }
function MSTRINGS(id, code, s) {
  const m = ABC.modules.find(m => m.id === id);
  if (!m) { ABC.errors.push(`module strings for unknown module "${id}"`); return; }
  m.strings[code] = abcMerge(m.strings[code] || {}, s);
}
// VIEW (abc/core/views/*.js) — a screen type; its element `el` is created in the stage if abc.html has none:
//   required: el, show(sayIt), announce(languageName)
//   optional: step(d), leave(), onKey(key, e) → handled?, resize(), play(), reset(), beforeLang() → state, afterLang(state),
//             arrows (‹ › paging), nav (id of its own bottom bar), swipe, fullHeight, keepScroll, indexFace(item) → HTML, indexSort
// GAME (abc/core/games/*.js) — hosted by the 'play' view: { needs (min. items, default 2), pool(items, streak) → candidates,
//   prompt(target, round) → HTML of the question }
function VIEW(id, def) { ABC.views[id] = Object.assign({ id }, def); }
function GAME(id, def) { ABC.games[id] = Object.assign({ id }, def); }
